import {ControlGroup} from '@github-ui/control-group'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {ReposSelectPanelWrapper, type ReposSelectPanelWrapperItem} from '@github-ui/repos-select-panel-wrapper'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {FileIcon, LawIcon} from '@primer/octicons-react'
import {Link} from '@primer/react'
import {useEffect, useState} from 'react'

import type {CreateFormPayload, License} from '../types/repo-creation-types'

export function InitializeRepositoryOptions({
  docsUrls,
  addReadme,
  onAddReadmeChange,
  selectedGitignoreTemplate,
  onSelectedGitignoreTemplateChange,
  licenses,
  selectedLicense,
  onSelectedLicenseChange,
  isGitHubEnterprise,
}: {
  docsUrls: CreateFormPayload['docsUrls']
  addReadme: boolean
  onAddReadmeChange: (newVal: boolean) => void
  selectedGitignoreTemplate: ReposSelectPanelWrapperItem
  onSelectedGitignoreTemplateChange: (newTemplate: ReposSelectPanelWrapperItem) => void
  licenses: License[]
  selectedLicense: License
  onSelectedLicenseChange: (newLicense: License) => void
  isGitHubEnterprise: boolean
}) {
  return (
    <ControlGroup>
      <ControlGroup.Item>
        <ControlGroup.Title className="fgColor-default" id="add-readme">
          Add README
        </ControlGroup.Title>
        <ControlGroup.Description>
          READMEs can be used as longer descriptions.{' '}
          <Link href={docsUrls.readme} target="_blank" inline muted>
            About READMEs
          </Link>
        </ControlGroup.Description>
        <ControlGroup.ToggleSwitch
          aria-labelledby="add-readme"
          checked={addReadme}
          onClick={e => {
            e.preventDefault()
            onAddReadmeChange(!addReadme)
          }}
        />
      </ControlGroup.Item>
      <GitignoreDropdown {...{docsUrls, selectedGitignoreTemplate, onSelectedGitignoreTemplateChange}} />
      {!isGitHubEnterprise && <LicensePicker {...{docsUrls, licenses, selectedLicense, onSelectedLicenseChange}} />}
    </ControlGroup>
  )
}

function GitignoreDropdown({
  docsUrls,
  selectedGitignoreTemplate,
  onSelectedGitignoreTemplateChange,
}: {
  docsUrls: CreateFormPayload['docsUrls']
  selectedGitignoreTemplate: ReposSelectPanelWrapperItem
  onSelectedGitignoreTemplateChange: (newTemplate: ReposSelectPanelWrapperItem) => void
}) {
  const [templates, setTemplates] = useState<ReposSelectPanelWrapperItem[]>([])

  // selectedGitignoreTemplate defaults to the "No gitignore" item created in the form component
  useEffect(() => {
    const getItems = async () => {
      const response = await verifiedFetchJSON('/site/gitignore/templates')
      if (!response.ok) {
        setTemplates([selectedGitignoreTemplate])
        return
      }

      try {
        const serverTemplates: string[] = await response.json()
        const mapped = serverTemplates.map(t => ({text: t, id: t}))
        setTemplates([selectedGitignoreTemplate, ...mapped])
      } catch {
        setTemplates([selectedGitignoreTemplate])
      }
    }

    getItems()
    // only want this to run once when the component loads the first time
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const a11yGitignoreDropdown = isFeatureEnabled('a11y_gitignore_dropdown')

  return (
    <ControlGroup.Item>
      <ControlGroup.Title className="fgColor-default" id="add-gitignore">
        Add .gitignore
      </ControlGroup.Title>
      <ControlGroup.Description>
        .gitignore tells git which files not to track.{' '}
        <Link href={docsUrls.gitignore} target="_blank" inline muted>
          About ignoring files
        </Link>
      </ControlGroup.Description>
      <ControlGroup.Custom>
        <ReposSelectPanelWrapper
          title="Choose a .gitignore template"
          inputLabel=".gitignore template filter"
          placeholderText="Search templates"
          items={templates}
          selectedItem={selectedGitignoreTemplate}
          onSelect={onSelectedGitignoreTemplateChange}
          anchorButtonSelectedIcon={FileIcon}
          anchorButtonDescribedBy="add-gitignore"
          textInputLabelledBy="add-gitignore"
          _PrivateFocusManagement={a11yGitignoreDropdown ? 'roving-tabindex' : 'active-descendant'}
        />
      </ControlGroup.Custom>
    </ControlGroup.Item>
  )
}

function LicensePicker({
  docsUrls,
  licenses,
  selectedLicense,
  onSelectedLicenseChange,
}: {
  docsUrls: CreateFormPayload['docsUrls']
  licenses: License[]
  selectedLicense: License
  onSelectedLicenseChange: (newLicense: License) => void
}) {
  const a11yGitignoreDropdown = isFeatureEnabled('a11y_gitignore_dropdown')

  return (
    <ControlGroup.Item>
      <ControlGroup.Title className="fgColor-default" id="add-license">
        Add license
      </ControlGroup.Title>
      <ControlGroup.Description>
        Licenses explain how others can use your code.{' '}
        <Link href={docsUrls.license} target="_blank" inline muted>
          About licenses
        </Link>
      </ControlGroup.Description>
      <ControlGroup.Custom>
        <ReposSelectPanelWrapper
          title="Choose a license"
          inputLabel="License filter"
          placeholderText="Search licenses"
          items={licenses}
          selectedItem={selectedLicense}
          onSelect={onSelectedLicenseChange}
          anchorButtonSelectedIcon={LawIcon}
          anchorButtonDescribedBy="add-license"
          textInputLabelledBy="add-license"
          _PrivateFocusManagement={a11yGitignoreDropdown ? 'roving-tabindex' : 'active-descendant'}
        />
      </ControlGroup.Custom>
    </ControlGroup.Item>
  )
}

try{ InitializeRepositoryOptions.displayName ||= 'InitializeRepositoryOptions' } catch {}
try{ GitignoreDropdown.displayName ||= 'GitignoreDropdown' } catch {}
try{ LicensePicker.displayName ||= 'LicensePicker' } catch {}