import {Banner, Text} from '@primer/react'

export function ImmutableReleaseWarningBanner({nwo}: {nwo: string}) {
  return (
    <Banner variant="warning" title="Warning" hideTitle>
      <Banner.Description>
        The name <Text weight="semibold">{nwo}</Text> has been used before with immutable releases. You can create a
        repository with this name but will be blocked from using any existing legacy immutable release tags.
      </Banner.Description>
    </Banner>
  )
}

try{ ImmutableReleaseWarningBanner.displayName ||= 'ImmutableReleaseWarningBanner' } catch {}