import {ControlGroup} from '@github-ui/control-group'
import type {Visibility} from '@github-ui/repos-list/repos-list-types'
import type {SafeHTMLString} from '@github-ui/safe-html'
import {VerifiedHTMLBox} from '@github-ui/safe-html/VerifiedHTML'
import {testIdProps} from '@github-ui/test-id-props'
import {LockIcon, OrganizationIcon, RepoIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Banner} from '@primer/react'

import {capitalize} from '../helpers/capitalize'
import {
  isAdminOfTradeRestrictedOrg,
  isIndividualTradeRestricted,
  type VisibilityWithRestriction,
} from '../helpers/visibility'
import type {OwnerSelection} from '../types/repo-creation-types'

export function ModernVisibilitySelection({
  ownerSelection,
  privateModeEnabled,
  displayedVisibilities,
  selectedVisibility,
  onVisibilityChange,
  tradeControlsPrivateRepoCreationWarning,
  tradeControlsUserPrivateRepoCreationWarning,
  currentUserIsEnterpriseManaged,
}: {
  ownerSelection?: OwnerSelection
  privateModeEnabled: boolean
  displayedVisibilities: VisibilityWithRestriction[]
  selectedVisibility: Visibility
  onVisibilityChange: (value: Visibility) => void
  tradeControlsPrivateRepoCreationWarning: SafeHTMLString
  tradeControlsUserPrivateRepoCreationWarning: SafeHTMLString
  currentUserIsEnterpriseManaged: boolean
}) {
  const dropdownButton = (() => {
    const leadingVisual = (() => {
      switch (selectedVisibility) {
        case 'public':
          return <RepoIcon />
        case 'internal':
          return <OrganizationIcon />
        case 'private':
          return <LockIcon />
      }
    })()

    return (
      <ActionMenu.Button
        id="visibility-anchor-button"
        leadingVisual={leadingVisual}
        {...testIdProps('visibility-dropdown')}
      >
        {capitalize(selectedVisibility)}
      </ActionMenu.Button>
    )
  })()

  const ownerBusinessName = ownerSelection?.businessName
  const tradeRestrictionMessage = getTradeRestrictionMessage({
    ownerSelection,
    tradeControlsPrivateRepoCreationWarning,
    tradeControlsUserPrivateRepoCreationWarning,
  })

  return (
    <>
      {tradeRestrictionMessage && (
        <Banner variant="warning" title="Visibility options restricted due to regional policies">
          <VerifiedHTMLBox html={tradeRestrictionMessage} />
        </Banner>
      )}
      <ControlGroup>
        <ControlGroup.Item>
          <ControlGroup.Title className="fgColor-default">
            Choose visibility <span>*</span>
          </ControlGroup.Title>
          <ControlGroup.Description>Choose who can see and commit to this repository</ControlGroup.Description>
          <ControlGroup.Custom>
            <ActionMenu>
              {dropdownButton}
              <ActionMenu.Overlay width="medium">
                <ActionList selectionVariant="single">
                  {!currentUserIsEnterpriseManaged && (
                    <VisibilitySelectionItem
                      selectionItemVisibility="public"
                      leadingVisual={<RepoIcon />}
                      description={`${
                        privateModeEnabled ? 'Any logged in user' : 'Anyone on the internet'
                      } can see this repository. You choose who can commit.`}
                      displayedVisibilities={displayedVisibilities}
                      selectedVisibility={selectedVisibility}
                      onVisibilityChange={onVisibilityChange}
                    />
                  )}
                  {ownerBusinessName && (
                    <VisibilitySelectionItem
                      selectionItemVisibility="internal"
                      leadingVisual={<OrganizationIcon />}
                      description={`${ownerBusinessName} enterprise members can see this repository. You choose who can commit.`}
                      displayedVisibilities={displayedVisibilities}
                      selectedVisibility={selectedVisibility}
                      onVisibilityChange={onVisibilityChange}
                    />
                  )}
                  <VisibilitySelectionItem
                    selectionItemVisibility="private"
                    leadingVisual={<LockIcon />}
                    description="You choose who can see and commit to this repository."
                    displayedVisibilities={displayedVisibilities}
                    selectedVisibility={selectedVisibility}
                    onVisibilityChange={onVisibilityChange}
                  />
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          </ControlGroup.Custom>
        </ControlGroup.Item>
      </ControlGroup>
    </>
  )
}

const getTradeRestrictionMessage = ({
  ownerSelection,
  tradeControlsPrivateRepoCreationWarning,
  tradeControlsUserPrivateRepoCreationWarning,
}: {
  ownerSelection?: OwnerSelection
  tradeControlsPrivateRepoCreationWarning: SafeHTMLString
  tradeControlsUserPrivateRepoCreationWarning: SafeHTMLString
}) => {
  if (!ownerSelection) {
    return
  }

  if (isIndividualTradeRestricted(ownerSelection)) {
    return tradeControlsUserPrivateRepoCreationWarning
  }

  if (isAdminOfTradeRestrictedOrg(ownerSelection)) {
    return tradeControlsPrivateRepoCreationWarning
  }
}

function VisibilitySelectionItem({
  leadingVisual,
  description,
  selectionItemVisibility,
  selectedVisibility,
  displayedVisibilities,
  onVisibilityChange,
}: {
  leadingVisual: React.ReactNode
  description: string
  selectionItemVisibility: Visibility
  selectedVisibility: Visibility
  displayedVisibilities: VisibilityWithRestriction[]
  onVisibilityChange: (visibility: Visibility) => void
}) {
  const visibilityRestriction = displayedVisibilities.find(x => x.visibility === selectionItemVisibility)?.message
  const isSelected = selectedVisibility === selectionItemVisibility
  return (
    <ActionList.Item
      inactiveText={visibilityRestriction}
      selected={isSelected}
      onSelect={() => onVisibilityChange(selectionItemVisibility)}
    >
      <ActionList.LeadingVisual>{leadingVisual}</ActionList.LeadingVisual>
      {capitalize(selectionItemVisibility)}
      <ActionList.Description variant="block">{description}</ActionList.Description>
    </ActionList.Item>
  )
}

try{ ModernVisibilitySelection.displayName ||= 'ModernVisibilitySelection' } catch {}
try{ VisibilitySelectionItem.displayName ||= 'VisibilitySelectionItem' } catch {}