import {isFeatureEnabled} from '@github-ui/feature-flags'
import {Banner} from '@primer/react'

import type {OwnerSelection} from '../types/repo-creation-types'

export function ReadmeProfileBanner({
  ownerSelection,
  publicReposAvailable,
  repositoryName,
}: {
  ownerSelection?: OwnerSelection
  publicReposAvailable: boolean
  repositoryName: string
}) {
  let content
  if (
    publicReposAvailable &&
    !ownerSelection?.isOrganization &&
    repositoryName.toLowerCase() === ownerSelection?.name.toLowerCase()
  ) {
    content = (
      <div>
        <strong>
          {ownerSelection?.name}/{repositoryName}
        </strong>{' '}
        is a ✨<em>special</em> ✨ repository that you can use to add a <code>README.md</code> to your GitHub profile.
        Make sure it&rsquo;s public and initialize it with a <strong>README</strong> to get started.
      </div>
    )
  } else if (
    (ownerSelection?.isOrganization || isFeatureEnabled('alternate_user_config_repo')) &&
    !ownerSelection?.enterpriseManagedUserEnabled &&
    publicReposAvailable &&
    repositoryName.toLowerCase() === '.github'
  ) {
    content = (
      <div>
        <strong>{ownerSelection?.name}/.github</strong> is a ✨<em>special</em> ✨ repository that you can use to add a{' '}
        <code>README.md</code> to your public {ownerSelection?.isOrganization ? 'organization' : ''} profile, visible to
        anyone. Make sure it&rsquo;s public and initialize it with a <strong>README</strong> in the{' '}
        <strong>profile</strong> directory to get started.
      </div>
    )
  } else if (ownerSelection?.isOrganization && repositoryName.toLowerCase() === '.github-private') {
    content = (
      <div>
        <strong>{ownerSelection?.name}/.github-private</strong> is a ✨<em>special</em> ✨ repository that you can use
        to add a <code>README.md</code> to your organization member profile, visible only to organization members. Make
        sure it&rsquo;s private and initialize it with a <strong>README</strong> in the <strong>profile</strong>{' '}
        directory to get started.
      </div>
    )
  }

  return (
    content && (
      <Banner
        title="Special profile readme repository"
        hideTitle
        data-testid="special-repo-name-banner"
        description={content}
      />
    )
  )
}

try{ ReadmeProfileBanner.displayName ||= 'ReadmeProfileBanner' } catch {}